css:
:root { --sidenav-w: 256px; }
.shell { display: grid; grid-template-columns: var(--sidenav-w) minmax(0, 1fr); align-items: start; }
.docs-sidenav { position: sticky; top: var(--header-h); align-self: start; height: calc(100vh - var(--header-h)); overflow-y: auto; overscroll-behavior: contain; padding: 24px 22px 48px 0; border-right: 1px solid var(--pds-border-subtle); scrollbar-width: thin; }
.docs-sidenav__inner { display: flex; flex-direction: column; gap: 2px; }
.docs-sidenav__cat { margin-bottom: 4px; }
.docs-sidenav__cat > summary { list-style: none; cursor: pointer; font-family: var(--pds-font-display, var(--pds-font-body)); font-size: 11px; font-weight: 700; letter-spacing: 0.09em; text-transform: uppercase; color: var(--pds-text-secondary); padding: 8px 10px 6px; border-radius: 7px; user-select: none; display: flex; align-items: center; gap: 6px; }
.docs-sidenav__cat > summary::-webkit-details-marker { display: none; }
.docs-sidenav__cat > summary::before { content: '\203a'; display: inline-block; font-size: 13px; color: var(--pds-text-tertiary); transition: transform 0.15s ease; }
.docs-sidenav__cat[open] > summary::before { transform: rotate(90deg); }
.docs-sidenav__list { list-style: none; margin: 2px 0 8px; padding: 0; }
.docs-sidenav__link { display: block; padding: 6px 10px 6px 24px; border-radius: 7px; font-size: 13.5px; line-height: 1.35; color: var(--pds-text-secondary); text-decoration: none; border-left: 2px solid transparent; transition: background 0.12s ease, color 0.12s ease; }
.docs-sidenav__link:hover { background: var(--pds-surface-hover); color: var(--pds-text-primary); }
.docs-sidenav__link.is-active { color: var(--pds-link); font-weight: 600; background: var(--pds-surface-layer-accent); border-left-color: var(--pds-link); }
@media (max-width: 1023px) { .shell { grid-template-columns: minmax(0, 1fr); } .docs-sidenav { display: none; } }
